fn control_demands<T:RetireOwned>(owner:&ControlledRetirement<T>,body:usize)->Result<RetirementDemand,ValueError>{if owner.terminal_is_empty(){return Ok(RetirementDemand{depth:1,..Default::default()});}let copy=owner.next_copy_byte_demand()?;Ok(RetirementDemand{copy_bytes:copy,capacity_bytes:owner.next_capacity_byte_demand(body.max(copy))?,release_bytes:owner.next_release_byte_demand()?,depth:owner.next_depth_demand()?})}
