 pub fn new(original:ToolRunPresentation,tick:ToolRunTick,end:u32,state:ToolRunState,rate:f32,conflicts:u32)->Self{let step_sequence=original.body().progress.steps.newest().map_or(0,|step|step.sequence);Self{state:ManuallyDrop::new(State{original:Some(original),tick,end,state,rate,conflicts,capture:None,source:None,clone:None,clone_close:None,progress:None,counter_close:None,steps:VecDeque::new(),ring:None,ring_close:None,provenance_capture:None,provenance:None,provenance_close:None,projected:None,tool_id:None,payload:None,output:None,step_sequence,phase:0,cancelled:false}),transferred:false}}
 pub fn complete(&self)->bool{self.state.phase==17&&!self.state.cancelled}
 pub fn cancel(&mut self){self.state.cancelled=true;if let Some(child)=self.state.clone.as_mut(){child.cancel();}if let Some(child)=self.state.ring.as_mut(){child.cancel();}if let Some(child)=self.state.provenance.as_mut(){child.cancel();}}
